// Paste your OpenWeatherMap API key between the quotes below.
const API_KEY = "PASTE_YOUR_OPENWEATHER_API_KEY_HERE";
if (!API_KEY || API_KEY === "PASTE_YOUR_OPENWEATHER_API_KEY_HERE") {
    node.error("Add your OpenWeatherMap API key in the Build Chennai API URL function node.", msg);
    return null;
}
msg.method = "GET";
msg.url = "https://api.openweathermap.org/data/2.5/weather?q=Chennai,IN&appid=" +
    encodeURIComponent(API_KEY) + "&units=metric";
return msg;

const d = msg.payload;
if (!d || !d.main || !Array.isArray(d.weather) || !d.weather[0]) {
    node.error("Invalid OpenWeatherMap response. Check API key, internet, and API response.", msg);
    return null;
}
const p = {
    source: "openweathermap",
    city: d.name || "Chennai",
    temperature: Number(d.main.temp),
    humidity: Number(d.main.humidity),
    pressure: Number(d.main.pressure),
    condition: String(d.weather[0].main || "Unknown"),
    description: String(d.weather[0].description || ""),
    updated: new Date().toISOString()
};
if (![p.temperature, p.humidity, p.pressure].every(Number.isFinite)) {
    node.error("Weather API returned invalid numeric values.", msg);
    return null;
}
msg.topic = "snuc-iot/chennai/weather";
msg.payload = p;
return msg;

let d = msg.payload;
if (typeof d === "string") {
    try { d = JSON.parse(d); }
    catch (e) { node.warn("Ignoring non-JSON MQTT message"); return null; }
}
if (!d || typeof d !== "object") return null;

const state = flow.get("weatherState") || { bme: null, api: null };
if (msg.topic === "snuc-iot/stm32-bme280/node1") {
    const t = Number(d.temperature), h = Number(d.humidity), p = Number(d.pressure);
    if (![t, h, p].every(Number.isFinite)) {
        node.warn("BME280 JSON must contain numeric temperature, humidity and pressure.");
        return null;
    }
    state.bme = { temperature: t, humidity: h, pressure: p, updated: new Date().toISOString() };
} else if (msg.topic === "snuc-iot/chennai/weather") {
    const t = Number(d.temperature), h = Number(d.humidity), p = Number(d.pressure);
    if (![t, h, p].every(Number.isFinite)) {
        node.warn("Chennai API JSON must contain numeric temperature, humidity and pressure.");
        return null;
    }
    state.api = {
        temperature: t, humidity: h, pressure: p,
        condition: String(d.condition || "Unknown"),
        description: String(d.description || ""),
        updated: d.updated || new Date().toISOString()
    };
} else {
    return null;
}
flow.set("weatherState", state);

const b = state.bme, a = state.api;
const rainSignal = !!a && (/rain|drizzle|thunderstorm/i.test(a.condition) ||
    (a.humidity >= 80 && a.pressure <= 1005));
const inferences = [
    {
        title: "Rain-related conditions",
        level: rainSignal ? "warning" : "normal",
        text: !a ? "Waiting for Chennai API data." :
            (rainSignal ? "Rain is reported or humidity and pressure suggest possible unsettled weather." :
            "No strong rain signal from the current API conditions.")
    },
    {
        title: "High humidity",
        level: a && a.humidity >= 70 ? "warning" : "normal",
        text: !a ? "Waiting for Chennai API humidity." :
            (a.humidity >= 70 ? "Chennai humidity is high; the air may feel sticky." :
            "Chennai humidity is below the high-humidity threshold.")
    },
    {
        title: "Indoor vs outdoor temperature",
        level: b && a && Math.abs(b.temperature - a.temperature) > 2 ? "info" : "normal",
        text: !b || !a ? "Waiting for both BME280 and API readings." :
            (b.temperature > a.temperature + 2 ?
                "The BME280 location is over 2°C warmer than Chennai's API reading." :
             b.temperature < a.temperature - 2 ?
                "The BME280 location is over 2°C cooler than Chennai's API reading." :
                "The two temperature readings are within 2°C.")
    },
    {
        title: "Atmospheric pressure",
        level: a && a.pressure < 1008 ? "info" : "normal",
        text: !a ? "Waiting for Chennai API pressure." :
            (a.pressure < 1008 ? "Pressure is relatively low; unsettled weather is possible." :
            "Pressure is not below the simple low-pressure threshold.")
    }
];
msg.payload = { bme: b, api: a, inferences: inferences, receivedAt: new Date().toISOString() };
return msg;
